  ∀ (g rsqrt_v : Float), RmsNormBackwardSpec.grad_weight_element g 0.0 rsqrt_v = g * 0.0 * rsqrt_v :=
  fun _ _ => Eq.refl _

theorem grad_input_formula :
  ∀ (g w x rv rc sgwx n : Float),
