  fun _ _ _ _ _ _ _ => Eq.refl _

theorem normalize_element_def :
  ∀ (x w rv : Float), RmsNormSpec.normalize_element x w rv = x * rv * w :=
  fun _ _ _ => Eq.refl _

theorem sum_sq_singleton :
  ∀ (x : Float), RmsNormSpec.sum_sq [x] = x * x + 0.0 :=
  fun _ => Eq.refl _

theorem sum_list_singleton :
  ∀ (x : Float), LayerNormSpec.sum_list [x] = x + 0.0 :=
  fun _ => Eq.refl _

theorem sum_exp_singleton :
  ∀ (x m : Float), SoftmaxSpec.sum_exp [x] m = Float.exp (x - m) + 0.0 :=
  fun _ _ => Eq.refl _

theorem find_max_singleton :
  ∀ (x : Float), SoftmaxSpec.find_max [x] = if x > Float.negInf then x else Float.negInf :=
  fun _ => Eq.refl _

