            mean += bfloat16ToFloat(input[row_start + i]);
        }
        mean = mean / ns_f;

        var variance: f32 = 0.0;
        i = 0;
        while (i < normalized_shape) : (i += 1) {
            const val = bfloat16ToFloat(input[row_start + i]);
            const diff = val - mean;
            variance += diff * diff;
        }
        variance = variance / ns_f;

        const inv_std = 1.0 / @sqrt(variance + eps);

        i = 0;
        while (i < normalized_shape) : (i += 1) {
            const val = bfloat16ToFloat(input[row_start + i]);
            const w = bfloat16ToFloat(weight[i]);
            const b_val: f32 = if (bias) |b| bfloat16ToFloat(b[i]) else 0.0;
            const normalized = (val - mean) * inv_std;
            output[row_start + i] = floatToBFloat16(normalized * w + b_val);
        }
    }
}

pub fn geluForward(
    input: []const BFloat16,
    output: []BFloat16,
    numel: usize,
    approximate: bool,
) KernelError!void {
    if (input.len < numel) return KernelError.InvalidArgument;
    if (output.len < numel) return KernelError.InvalidArgument;

    var i: usize = 0;
    while (i < numel) : (i += 1) {
        const x = bfloat16ToFloat(input[i]);
        const y = if (approximate) geluApproximate(x) else geluExact(x);
        output[i] = floatToBFloat16(y);
    }
}

fn geluApproximate(x: f32) f32 {
    const sqrt_2_over_pi: f32 = 0.7978845608028654;
    const x3 = x * x * x;
    const tanh_arg = sqrt_2_over_pi * (x + 0.044715 * x3);
    return 0.5 * x * (1.0 + math.tanh(tanh_arg));
}

fn geluExact(x: f32) f32 {
    const sqrt2: f32 = 1.4142135623730951;
    const erf_val = erff(x / sqrt2);
    return 0.5 * x * (1.0 + erf_val);
}

fn erff(x: f32) f32 {
    const a1: f32 = 0.254829592;
    const a2: f32 = -0.284496736;
    const a3: f32 = 1.421413741;
    const a4: f32 = -1.453152027;
    const a5: f32 = 1.061405429;
    const p: f32 = 0.3275911;

    const sign: f32 = if (x < 0.0) -1.0 else 1.0;
    const abs_x = @abs(x);
    const t = 1.0 / (1.0 + p * abs_x);
    const y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * @exp(-abs_x * abs_x);
    return sign * y;
}

pub fn geluBackward(
    grad_output: []const BFloat16,
    input: []const BFloat16,
    grad_input: []BFloat16,
    numel: usize,
    approximate: bool,
) KernelError!void {
    if (grad_output.len < numel) return KernelError.InvalidArgument;
    if (input.len < numel) return KernelError.InvalidArgument;
    if (grad_input.len < numel) return KernelError.InvalidArgument;

    var i: usize = 0;
    while (i < numel) : (i += 1) {
        const x = bfloat16ToFloat(input[i]);
        const g = bfloat16ToFloat(grad_output[i]);

        const grad_val = if (approximate) geluApproxBackward(x) else geluExactBackward(x);
        grad_input[i] = floatToBFloat16(g * grad_val);
    }
}

fn geluApproxBackward(x: f32) f32 {
    const sqrt_2_over_pi: f32 = 0.7978845608028654;
    const x3 = x * x * x;
    const tanh_arg = sqrt_2_over_pi * (x + 0.044715 * x3);
    const tanh_val = math.tanh(tanh_arg);
    const sech_sq = 1.0 - tanh_val * tanh_val;
    const inner_deriv = sqrt_2_over_pi * (1.0 + 3.0 * 0.044715 * x * x);
    return 0.5 * (1.0 + tanh_val) + 0.5 * x * sech_sq * inner_deriv;
}

fn geluExactBackward(x: f32) f32 {
    const sqrt2: f32 = 1.4142135623730951;
    const cdf = 0.5 * (1.0 + erff(x / sqrt2));
    const pdf = @exp(-0.5 * x * x) * 0.3989422804014327;
    return cdf + x * pdf;
}

pub fn softmaxForward(
    input: []const BFloat16,
    output: []BFloat16,
    outer_size: usize,
    dim_size: usize,
    inner_size: usize,
) KernelError!void {
    if (dim_size == 0) return KernelError.DivisionByZero;
    if (inner_size == 0) return KernelError.InvalidArgument;
    if (outer_size == 0) return;

    const total = outer_size * dim_size * inner_size;
    if (input.len < total) return KernelError.InvalidArgument;
    if (output.len < total) return KernelError.InvalidArgument;

    var outer: usize = 0;
    while (outer < outer_size) : (outer += 1) {
        var inner: usize = 0;
        while (inner < inner_size) : (inner += 1) {
            const base = outer * dim_size * inner_size + inner;

            var max_val: f32 = -math.inf(f32);
            var d: usize = 0;
            while (d < dim_size) : (d += 1) {
                const val = bfloat16ToFloat(input[base + d * inner_size]);
                if (val > max_val) {
                    max_val = val;
                }
            }

            var sum_exp: f32 = 0.0;
            d = 0;
            while (d < dim_size) : (d += 1) {
                const val = bfloat16ToFloat(input[base + d * inner_size]);
                const exp_val = @exp(val - max_val);
                sum_exp += exp_val;
                output[base + d * inner_size] = floatToBFloat16(exp_val);
            }

            if (sum_exp == 0.0) {
                const uniform: f32 = 1.0 / @as(f32, @floatFromInt(dim_size));
                d = 0;
                while (d < dim_size) : (d += 1) {
                    output[base + d * inner_size] = floatToBFloat16(uniform);
                }
            } else {
                d = 0;
                while (d < dim_size) : (d += 1) {
                    const val = bfloat16ToFloat(output[base + d * inner_size]);
                    output[base + d * inner_size] = floatToBFloat16(val / sum_exp);
                }
            }
        }
    }
}

pub fn validateNormArgs(numel: usize, normalized_shape: usize) KernelError!struct { n_rows: usize, block_size: usize } {
    if (normalized_shape == 0) return KernelError.DivisionByZero;
    if (numel % normalized_shape != 0) return KernelError.DimensionMismatch;
    const n_rows = numel / normalized_shape;
    if (n_rows == 0) return KernelError.InvalidArgument;
    const block_size = if (normalized_shape < 256) normalized_shape else 256;
    if (block_size == 0) return KernelError.InvalidArgument;
    return .{ .n_rows = n_rows, .block_size = block_size };
}
def RmsNormSpec.sum_sq (xs : List Float) : Float :=
  match xs with
  | [] => 0.0
  | x :: rest => x * x + RmsNormSpec.sum_sq rest

def RmsNormSpec.mean_sq (xs : List Float) (n : Nat) (hn : n > 0) : Float :=
  RmsNormSpec.sum_sq xs / Float.ofNat n

def RmsNormSpec.rsqrt_val (mean_sq_val : Float) (eps : Float) : Float :=
  1.0 / Float.sqrt (mean_sq_val + eps)

def RmsNormSpec.normalize_element (x : Float) (w : Float) (rsqrt_v : Float) : Float :=
  x * rsqrt_v * w

def RmsNormSpec.forward_row (row : List Float) (weight : List Float) (eps : Float) (n : Nat) (hn : n > 0) : List Float :=
  match row, weight with
  | [], [] => []
  | x :: xs, w :: ws =>
    (RmsNormSpec.normalize_element x w (RmsNormSpec.rsqrt_val (RmsNormSpec.mean_sq (x :: xs) n hn) eps)) ::
    (match xs, ws with
     | [], [] => []
     | _ :: _, _ :: _ => RmsNormSpec.forward_row xs ws eps n hn
     | _, _ => [])
  | _, _ => []

def LayerNormSpec.sum_list (xs : List Float) : Float :=
  match xs with
  | [] => 0.0
  | x :: rest => x + LayerNormSpec.sum_list rest

def LayerNormSpec.mean_list (xs : List Float) (n : Nat) (hn : n > 0) : Float :=
  LayerNormSpec.sum_list xs / Float.ofNat n

def LayerNormSpec.variance_from_mean (xs : List Float) (m : Float) (n : Nat) (hn : n > 0) : Float :=
  match xs with
  | [] => 0.0
  | x :: rest => ((x - m) * (x - m) + LayerNormSpec.variance_from_mean rest m n hn * Float.ofNat rest.length) / Float.ofNat (rest.length + 1)

inductive NormError where
  | divisionByZero : NormError
  | invalidArgument : NormError
  | dimensionMismatch : NormError
  | nullPointer : NormError

structure ValidateNormResult where
  n_rows : Nat
  block_size : Nat

def validateNormArgs (numel : Nat) (normalized_shape : Nat) : Except NormError ValidateNormResult :=
  if normalized_shape == 0 then
    Except.error NormError.divisionByZero
  else if numel % normalized_shape != 0 then
    Except.error NormError.dimensionMismatch
  else
    match numel / normalized_shape with
    | 0 => Except.error NormError.invalidArgument
    | n_rows =>
      match (if normalized_shape < 256 then normalized_shape else 256) with
      | 0 => Except.error NormError.invalidArgument
      | block_size => Except.ok { n_rows := n_rows, block_size := block_size }

def GeluSpec.approximate (x : Float) : Float :=
  0.5 * x * (1.0 + Float.tanh (0.7978845608028654 * (x + 0.044715 * x * x * x)))

def GeluSpec.exact_erf_approx (x : Float) : Float :=
  0.5 * x * (1.0 + Float.tanh (0.7978845608028654 * x))

def SoftmaxSpec.find_max (xs : List Float) : Float :=
  match xs with
  | [] => Float.negInf
  | x :: rest =>
    match SoftmaxSpec.find_max rest with
    | m => if x > m then x else m

def SoftmaxSpec.sum_exp (xs : List Float) (max_val : Float) : Float :=
  match xs with
  | [] => 0.0
  | x :: rest => Float.exp (x - max_val) + SoftmaxSpec.sum_exp rest max_val

def SoftmaxSpec.normalize (xs : List Float) (max_val : Float) (sum : Float) : List Float :=
  match xs with
  | [] => []
  | x :: rest => (Float.exp (x - max_val) / sum) :: SoftmaxSpec.normalize rest max_val sum

def SoftmaxSpec.forward (xs : List Float) : List Float :=
  match xs with
  | [] => []
  | _ =>
    SoftmaxSpec.normalize xs (SoftmaxSpec.find_max xs) (SoftmaxSpec.sum_exp xs (SoftmaxSpec.find_max xs))

def RmsNormBackwardSpec.grad_input_element (g : Float) (w : Float) (x : Float) (rsqrt_v : Float) (rsqrt_cubed : Float) (sum_gw_x : Float) (n : Float) : Float :=
  w * rsqrt_v * g - x * sum_gw_x * rsqrt_cubed / n

def RmsNormBackwardSpec.grad_weight_element (g : Float) (x : Float) (rsqrt_v : Float) : Float :=
  g * x * rsqrt_v

theorem validateNormArgs_rejects_zero_shape :
  ∀ (numel : Nat), validateNormArgs numel 0 = Except.error NormError.divisionByZero :=
  fun _ => Eq.refl _

theorem validateNormArgs_rejects_non_divisible :
  validateNormArgs 7 3 = Except.error NormError.dimensionMismatch :=
  Eq.refl _

theorem validateNormArgs_accepts_valid :
  validateNormArgs 12 4 = Except.ok { n_rows := 3, block_size := 4 } :=
  Eq.refl _

theorem softmax_empty_is_empty :
